bench_main_cpp:
#include <Arduino.h>
#include <Esp32LteClock.h>
#include <time.h>
static esp32_lte_time::Esp32LteClock clockReceiver;
static void progress(esp32_lte_time::ClockStatus status,const esp32_lte_time::ClockEvidence& e) {
  static auto last=esp32_lte_time::ClockStatus::Idle;
  if(status!=last){
    Serial.printf("TMOBILE_PROBE boot_ms=%u status=%u PCI=%u captures=%u MIBs=%u\n",millis(),unsigned(status),e.pci,e.captures,e.mibs);
    last=status;
  }
}
void setup(){
  Serial.begin(115200);
  Serial.println("TMOBILE_PROBE_START live RF, onboard decoding, no host time or serial input");
  esp32_lte_time::ClockConfig config;
  config.autoScan=false;config.cellTimeoutMs=45000;
  const unsigned carriers[]={2140,1955};
  const unsigned pcis[]={242,377};
  for(unsigned profile=0;profile<2;++profile){
    config.tuningMHz=carriers[profile]-1;config.carrierHz=carriers[profile]*1000000.0;
    config.pcis[0]=pcis[profile];config.pcis[1]=pcis[profile];
    for(unsigned trial=1;trial<=2;++trial){
      Serial.printf("TMOBILE_PROBE_TRIAL carrier_MHz=%u PCI=%u trial=%u\n",carriers[profile],pcis[profile],trial);
      bool synced=clockReceiver.sync(60000,config,progress);
      Serial.printf("TMOBILE_PROBE_RESULT carrier_MHz=%u PCI=%u trial=%u synced=%u status=%u captures=%u MIBs=%u ticks=%llu\n",carriers[profile],pcis[profile],trial,unsigned(synced),unsigned(clockReceiver.status()),clockReceiver.evidence().captures,clockReceiver.evidence().mibs,(unsigned long long)clockReceiver.evidence().rawTicks);
      if(synced)break;
      delay(1000);
    }
  }
  Serial.println("TMOBILE_PROBE_DONE");
}
void loop(){delay(1000);}

